import React, { useEffect, useState } from "react";
import { useParams, useNavigate } from "react-router-dom";
import { getDoctorById } from "../services/doctorService";
import { isLoggedIn } from "../utils/auth";

function BookAppointment() {
  const { doctorId } = useParams();
  const navigate = useNavigate();

  const [doctor, setDoctor] = useState(null);
  const [selectedDate, setSelectedDate] = useState("");
  const [selectedTime, setSelectedTime] = useState("");

  const timeSlots = ["10:00", "11:00", "12:00", "14:00", "16:00"];

  // ✅ FETCH DOCTOR FROM BACKEND
  useEffect(() => {
    fetchDoctor();
  }, [doctorId]);

  const fetchDoctor = async () => {
    try {
      const res = await getDoctorById(doctorId);
      console.log("DOCTOR:", res.data);
      setDoctor(res.data);
    } catch (err) {
      console.error("ERROR:", err);
    }
  };

  // ✅ BOOKING HANDLER
  const handleBooking = () => {
    if (!isLoggedIn()) {
      alert("Please login first");
      navigate("/login");
      return;
    }

    if (!selectedDate || !selectedTime) {
      alert("Select date & time");
      return;
    }

    console.log({
      doctorId,
      selectedDate,
      selectedTime,
    });

    alert("Booking Done ✅ (Next: connect API)");
  };

  if (!doctor) return <h3>Loading...</h3>;

  return (
    <div style={styles.container}>
      {/* Doctor Info */}
      <div style={styles.card}>
        <img src={doctor.image} alt="doctor" style={styles.image} />
        <h2>{doctor.name}</h2>
        <p>{doctor.specialization}</p>
      </div>

      {/* Booking Section */}
      <div style={styles.booking}>
        <h3>Select Date</h3>
        <input
          type="date"
          onChange={(e) => setSelectedDate(e.target.value)}
        />

        <h3>Select Time</h3>
        <div style={styles.slots}>
          {timeSlots.map((time) => (
            <button
              key={time}
              style={
                selectedTime === time
                  ? styles.selectedSlot
                  : styles.slot
              }
              onClick={() => setSelectedTime(time)}
            >
              {time}
            </button>
          ))}
        </div>

        <button style={styles.bookBtn} onClick={handleBooking}>
          Confirm Booking
        </button>
      </div>
    </div>
  );
}

const styles = {
  container: {
    padding: "20px",
  },
  card: {
    textAlign: "center",
    marginBottom: "20px",
  },
  image: {
    width: "100px",
    borderRadius: "50%",
  },
  booking: {
    textAlign: "center",
  },
  slots: {
    display: "flex",
    justifyContent: "center",
    gap: "10px",
    flexWrap: "wrap",
    margin: "10px 0",
  },
  slot: {
    padding: "8px 12px",
    border: "1px solid #1976d2",
    background: "#fff",
    cursor: "pointer",
    borderRadius: "5px",
  },
  selectedSlot: {
    padding: "8px 12px",
    border: "1px solid #1976d2",
    background: "#1976d2",
    color: "#fff",
    cursor: "pointer",
    borderRadius: "5px",
  },
  bookBtn: {
    marginTop: "15px",
    padding: "10px 20px",
    background: "green",
    color: "#fff",
    border: "none",
    borderRadius: "5px",
    cursor: "pointer",
  },
};

export default BookAppointment;
